 const autoStats=()=>{const hd=W.holdings.filter(h=>!(+h.proc>0&&!+h.shares)),val=sum(hd,h=>h.val),inv=sum(hd,h=>h.inv),ds=W.days,l=ds.length?ds[ds.length-1].d:'',pr=f=>{const a=ds.filter(f);return{p:comp(a.map(x=>x.p)),g:sum(a,x=>x.g)}},m=l?pr(x=>x.d.slice(0,7)==l.slice(0,7)):{p:0,g:0},y=l?pr(x=>x.d.slice(0,4)==l.slice(0,4)):{p:0,g:0};return{inv,val,gain:val-inv,gainp:inv?(val-inv)/inv*100:0,mtd:m.p,mtdg:m.g,ytd:y.p,ytdg:y.g}};
